# Ignore no unknown source: exact coverage asserted below.
files = subprocess.check_output(['git','ls-files','instructions.md','docs/agent','docs/reports'], text=True).splitlines()
entries = []
def add(source, action, destinations, topic, work, scope):
 p=ROOT/source; raw=p.read_bytes()
 entries.append(dict(source=source,sha256=hashlib.sha256(raw).hexdigest(),bytes=len(raw),action=action,destinations=destinations,topic=topic,required_work=work,target_search_scope=scope,headings=[l for l in p.read_text().splitlines() if l.startswith('#')] if p.suffix=='.md' else []))
add('instructions.md','rewrite in place',['instructions.md'],'Short task router','Keep setup, brief → retrieve → build → review → repair → deliver, essential coordinates and evidence rules. Link task guides and current CLI. Remove family default, copied hose schema, universal Halcyon/SNOT mandate, historical permission rules and project-local xray invocation. Target roughly 400–600 words; make it useful before adding extra rules.','default')
for source,action,dest,topic,work in rows:add('docs/agent/'+source,action,dest,topic,work,'research' if source=='verification.md' else 'default')
add('docs/agent/resources/bookshop-study.json','relocate evidence',['docs/reports/resources/bookshop-study.json'],'Bookshop source inventory','Preserve bytes/hash and connect to bookshop-source-audit; do not embed this source-specific inventory in default retrieval. Update the new report links and existing historical backlinks.','research')
for source in files:
 if not source.startswith('docs/reports/'):continue
 p=Path(source)
 if p.parent==Path('docs/reports') and p.suffix=='.md':
  dest,work=report_lessons[p.name]
  add(source,'retain history; extract only missing durable lessons',[source]+dest,'Dated report',work,'research')
 else:
  topic='Trial evidence' if 'authoring-trials/' in source else 'Report evidence or reproduction aid'
  work='Preserve this exact file with its containing evidence bundle, hashes, dates, model/settings, command timings, failures and original result. Do not promote delivered trial geometry or reclassify the corrected rerun as the original comparison.' if topic=='Trial evidence' else 'Preserve the JSON/CSV/script alongside its report and keep relative references working. No execution or regeneration is needed for relocation planning; historical costs and measurements remain dated.'
  add(source,'retain evidence in place',[source],topic,work,'research')
assert len(entries)==len(files)==len({e['source'] for e in entries})
assert set(files)=={e['source'] for e in entries}
by_source={e['source']:e for e in entries}
# All tracked Markdown inbound links, including example READMEs. Textual target scan;
# fragment validity and runtime string consumers are separate implementation checks.
links=[]
for name in subprocess.check_output(['git','ls-files','*.md'],text=True).splitlines():
 p=ROOT/name
 if not p.exists():continue
 for n,line in enumerate(p.read_text(errors='replace').splitlines(),1):
  for match in re.finditer(r'\]\(([^)]+)\)',line):
   target=match.group(1).strip().strip('<>');target=target.split(' "',1)[0]
   if re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:',target):continue
   path,_,fragment=target.partition('#')
   resolved=(p.parent/unquote(path)).resolve() if path else p.resolve()
   try:rel=str(resolved.relative_to(ROOT))
   except ValueError:continue
   if rel in by_source:links.append(dict(source=name,line=n,target=rel,fragment=fragment,exists=resolved.exists()))
for e in entries:e['inbound_markdown_links']=sum(l['target']==e['source'] for l in links)
agent_targets=sorted({d for e in entries for d in e['destinations'] if d.startswith('docs/agent/')})
result=dict(date='2026-11-02',status='planning_only',scope=['instructions.md','tracked docs/agent/**','tracked docs/reports/**'],review_basis='Document structure and task-relevant prose/contracts inspected; reports treated as dated evidence, not re-executed or independently revalidated. Structured companions inventoried and hashed, not semantically rewritten.',entries=entries,proposed_agent_documents=agent_targets,inbound_markdown_links=links,link_scan_limits='Inline Markdown file targets only; fragment/heading validity, reference-style links, HTML and runtime/test string consumers must be checked during implementation.')
(OUT/'document-migration-ledger.json').write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n')
lines=['# Documentation migration ledger','',f'Planning only, 2026-11-02. **{len(entries)} tracked sources mapped:** instructions, 30 agent Markdown documents, one agent evidence resource, and 71 report/evidence files. All source hashes are recorded in [the complete ledger](document-migration-ledger.json). No source has been moved or rewritten.','',f'The proposed agent documentation has **{len(agent_targets)} files**, plus the short entry point. This reduces duplicate ownership, not just file count. Search should retrieve headings/sections with parent context rather than loading an entire guide. Proposed paths are destinations, not currently available files.','','## Entry and agent documents','','| Existing source | Action and proposed destination | Required editorial work |','|---|---|---|']
for e in entries:
 if e['source'].startswith('docs/reports/'):continue
 dest='<br/>'.join('`'+d+'`' for d in e['destinations'])
 lines.append(f"| `{e['source']}` | **{e['action']}**<br/>{dest} | {e['required_work']} |")
lines+=['','## Reports: preserve history, extract narrowly','','Reports and evidence remain outside default construction retrieval. Extract a durable lesson only if its destination does not already teach it; link the report for provenance. Historical permissions, prices, test totals and measured timings do not become current instructions.','','| Report | Lesson destination | Action |','|---|---|---|']
for e in entries:
 if Path(e['source']).parent!=Path('docs/reports') or not e['source'].endswith('.md'):continue
 dest=', '.join('`'+d+'`' for d in e['destinations'][1:]) or 'None; historical provenance/research only'
 lines.append(f"| `{e['source']}` | {dest} | {e['required_work']} |")
lines+=['','## Every companion and trial record','','The following files each have their own source hash and retain-in-place decision in the JSON ledger. Preserve each bundle as a unit; no new visual acceptance is implied for its historical generated models.','','| File | Role |','|---|---|']
for e in entries:
 if e['source'].startswith('docs/reports/') and not(Path(e['source']).parent==Path('docs/reports') and e['source'].endswith('.md')):lines.append(f"| `{e['source']}` | {e['topic']} |")
lines+=['','## Link and contract migration','',''+str(len(links))+' inline Markdown references to these sources were found across tracked Markdown. The JSON records source file, line, target and fragment for each. This is a rewrite inventory, not a declaration that all existing anchors are valid.','', 'After the destination text exists, rewrite inbound paths and heading anchors, including example READMEs and preserved reports. For moved relative links, compute against the new directory; do not merely replace the basename. Use temporary redirect stubs only for externally used old paths, exclude stubs from search, and keep each claim authored in one place. No permanent duplicate guide is required.','', 'Update runtime/test consumers in the same migration as their docs: CLI family default in `ldraw_tools/cli.py`; hardcoded atlas routing in `ldraw_tools/examples.py`; Halcyon insertion/default policy in `ldraw_tools/spaceships.py`; bounded family-part checks in `ldraw_tools/vehicle_review.py`; filters and corpus scope in `ldraw_tools/discovery.py`; per-atlas generators and tests. Preserve explicit recipe checks while separating them from general subject classification.','', 'Before publication, check exact command examples against the local parser/help/schema; exercise changed retrieval/default behavior and the affected example export/build paths. A document-only move does not justify rerendering unchanged models or rerunning all historical experiments. Do not present proposed KB-search flags before implementation.','', 'For `ldraw-xray`, use the global executable, inspect its actual environment, and link upstream usage documentation. The existing Nova wrapper remains a compatibility implementation detail until separately changed; this plan does not assume it configures the global CLI.','', '## Remaining planning boundary','', 'This closes the per-document mapping. The individual visual findings already determine candidate dispositions. The [example-package ledger](example-migration-ledger.md) and [catalog/export compatibility plan](catalog-export-migration.md) now complete that consolidation. No new render sweep or agent trial was needed to prepare the handoff.','']
(OUT/'document-migration-ledger.md').write_text('\n'.join(lines))
print(json.dumps(dict(sources=len(entries),agent_destinations=len(agent_targets),inbound_links=len(links),source_categories=dict(Counter(e['target_search_scope'] for e in entries))),indent=2))
